{
  "name": "recorded-test",
  "version": "1.0.0",
  "private": true,
  "description": "Playwright tests for Recorded Test",
  "scripts": {
    "test": "npx playwright test",
    "test:headed": "npx playwright test --headed",
    "test:ui": "npx playwright test --ui",
    "report": "npx playwright show-report"
  },
  "devDependencies": {
    "@playwright/test": "^1.52.0"
  }
}

import { defineConfig, devices } from '@playwright/test';

/**
 * Playwright configuration for Recorded Test.
 * Generated by CmdRunner from the Execution IR.
 */
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'http://127.0.0.1:8845',
    viewport: { width: 780, height: 437 },
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
});

import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // NOTE: No assertions generated — assertion derivation is not available. This test replays actions only.

    // Hover over the Services Section
    await page.locator('#services').hover()
  });
});
